13	func digestOf(content string) string {
14		sum := sha256.Sum256([]byte(content))
15		return hex.EncodeToString(sum[:])
16	}
17	
18	func objectExists(root, digest string) bool {
19		_, err := os.Lstat(filepath.Join(root, "objects", digest))
20		return err == nil
21	}
22	
23	func TestGCCollectsOverwrittenAndOrphanedObjects(t *testing.T) {
24		root := filepath.Join(t.TempDir(), "vault")
25		store := New(root)
26		d1 := digestOf("one")
27		d2 := digestOf("two")
28		d3 := digestOf("three")
29	
30		if _, err := store.Put("a.txt", writeFile(t, "one")); err != nil {
31			t.Fatal(err)
32		}
33		if _, err := store.CreateSnapshot("snap/one"); err != nil {
34			t.Fatal(err)
35		}
36		// Overwrite a.txt; d1 survives only through the snapshot.
37		if _, err := store.Put("a.txt", writeFile(t, "two")); err != nil {
38			t.Fatal(err)
39		}
40		if _, err := store.Put("b.txt", writeFile(t, "three")); err != nil {
41			t.Fatal(err)
42		}
43		// Restore drops b.txt and the overwritten version from the mapping.
44		if err := store.RestoreSnapshot("snap/one"); err != nil {
45			t.Fatal(err)
46		}
47	
48		dry, err := store.GC(true)
49		if err != nil {
50			t.Fatal(err)
51		}
52		want := []string{d2, d3}
53		if d3 < d2 {
54			want = []string{d3, d2}
55		}
56		if len(dry.Candidates) != 2 {
57			t.Fatalf("dry-run candidates=%+v", dry.Candidates)
58		}
59		for i, candidate := range dry.Candidates {
60			if candidate.Digest != want[i] {
61				t.Fatalf("candidates[%d]=%q, want %q", i, candidate.Digest, want[i])
62			}
63		}
64		if dry.Deleted != 0 || dry.Bytes != 0 {
65			t.Fatalf("dry run deleted %d objects, %d bytes", dry.Deleted, dry.Bytes)
66		}
67		// Dry run deletes nothing.
68		for _, digest := range []string{d1, d2, d3} {
69			if !objectExists(root, digest) {
70				t.Fatalf("dry run removed object %s", digest)
71			}
72		}
73	
74		report, err := store.GC(false)
75		if err != nil {
76			t.Fatal(err)
77		}
78		if report.Deleted != 2 || report.Bytes != int64(len("two")+len("three")) {
79			t.Fatalf("deleted=%d bytes=%d", report.Deleted, report.Bytes)
80		}
81		if objectExists(root, d2) || objectExists(root, d3) {
82			t.Fatal("unreferenced objects survived GC")
83		}
84		// The snapshot-only object is kept and the snapshot still restores.
85		if !objectExists(root, d1) {
86			t.Fatal("snapshot-referenced object was collected")
87		}
88		if err := New(root).RestoreSnapshot("snap/one"); err != nil {
89			t.Fatal(err)
90		}
91		// A second pass finds nothing.
92		again, err := New(root).GC(false)
93		if err != nil {
94			t.Fatal(err)
95		}
96		if again.Deleted != 0 || again.Bytes != 0 || len(again.Candidates) != 0 {
97			t.Fatalf("second GC: %+v", again)
98		}
99	}
100	
101	func TestGCKeepsObjectsReferencedOnlyByNestedSnapshot(t *testing.T) {
102		root := filepath.Join(t.TempDir(), "vault")
103		store := New(root)
104		d1 := digestOf("one")
105		d2 := digestOf("two")
106		d3 := digestOf("three")
107		if _, err := store.Put("a.txt", writeFile(t, "one")); err != nil {
108			t.Fatal(err)
109		}
110		if _, err := store.CreateSnapshot("deep/nested/snap"); err != nil {
111			t.Fatal(err)
112		}
113		if _, err := store.Put("a.txt", writeFile(t, "two")); err != nil {
114			t.Fatal(err)
115		}
116		// d1 is now referenced only by the nested snapshot, d2 by the index:
117		// nothing may be collected.
118		report, err := store.GC(false)
119		if err != nil {
120			t.Fatal(err)
121		}
122		if report.Deleted != 0 || !objectExists(root, d1) || !objectExists(root, d2) {
123			t.Fatalf("deleted=%d d1=%v d2=%v", report.Deleted, objectExists(root, d1), objectExists(root, d2))
124		}
125		// Overwrite again: d2 loses its last reference and is collected, while
126		// d1 is still protected by the snapshot.
127		if _, err := store.Put("a.txt", writeFile(t, "three")); err != nil {
128			t.Fatal(err)
129		}
130		report, err = store.GC(false)
131		if err != nil {
132			t.Fatal(err)
133		}
134		if report.Deleted != 1 || !objectExists(root, d1) || objectExists(root, d2) || !objectExists(root, d3) {
135			t.Fatalf("deleted=%d d1=%v d2=%v d3=%v", report.Deleted,
136				objectExists(root, d1), objectExists(root, d2), objectExists(root, d3))
137		}
138		if err := store.RestoreSnapshot("deep/nested/snap"); err != nil {
139			t.Fatal(err)
140		}
141		output := filepath.Join(t.TempDir(), "out.txt")
142		if err := store.Get("a.txt", output); err != nil {
143			t.Fatal(err)
144		}
145		got, err := os.ReadFile(output)
146		if err != nil {
147			t.Fatal(err)
148		}
149		if string(got) != "one" {
150			t.Fatalf("content=%q", got)
151		}
152	}
153	
154	func TestGCSharedDigestIsOneObject(t *testing.T) {
155		root := filepath.Join(t.TempDir(), "vault")
156		store := New(root)
157		shared := digestOf("same payload")
158		input := writeFile(t, "same payload")
159		for _, name := range []string{"a.txt", "b.txt"} {
160			if _, err := store.Put(name, input); err != nil {
161				t.Fatal(err)
162			}
163		}
164		if _, err := store.CreateSnapshot("both"); err != nil {
165			t.Fatal(err)
166		}
167		// Referenced: nothing to collect.
168		report, err := store.GC(false)
169		if err != nil {
170			t.Fatal(err)
171		}
172		if report.Deleted != 0 {
173			t.Fatalf("deleted=%d", report.Deleted)
174		}
175		// Drop both names (restore an empty mapping) so the shared object is
176		// unreferenced: it is collected exactly once.
177		empty := `{"name":"empty","entries":{}}` + "\n"
178		if err := os.WriteFile(filepath.Join(root, "snapshots", "empty.json"), []byte(empty), 0o644); err != nil {
179			t.Fatal(err)
180		}
181		if err := os.Remove(filepath.Join(root, "snapshots", "both.json")); err != nil {
182			t.Fatal(err)
183		}
184		if err := store.RestoreSnapshot("empty"); err != nil {
185			t.Fatal(err)
186		}
187		report, err = store.GC(false)
188		if err != nil {
189			t.Fatal(err)
190		}
191		if report.Deleted != 1 || report.Bytes != int64(len("same payload")) {
192			t.Fatalf("deleted=%d bytes=%d", report.Deleted, report.Bytes)
193		}
194		if objectExists(root, shared) {
195			t.Fatal("shared object survived")
196		}
197	}
198	
199	func TestGCEmptyRepositoryAndIdempotence(t *testing.T) {
200		root := filepath.Join(t.TempDir(), "vault")
201		store := New(root)
202		if err := store.Init(); err != nil {
203			t.Fatal(err)
204		}
205		for _, dryRun := range []bool{true, false} {
206			report, err := store.GC(dryRun)
207			if err != nil {
208				t.Fatal(err)
209			}
210			if report.Deleted != 0 || report.Bytes != 0 || len(report.Candidates) != 0 {
211				t.Fatalf("dryRun=%v report=%+v", dryRun, report)
212			}
213		}
214		if _, err := store.Put("a.txt", writeFile(t, "data")); err != nil {
215			t.Fatal(err)
216		}
217		// Reopening the repository must not turn retained objects into candidates.
218		report, err := New(root).GC(false)
219		if err != nil {
220			t.Fatal(err)
221		}
222		if report.Deleted != 0 || len(report.Candidates) != 0 {
223			t.Fatalf("report=%+v", report)
224		}
225	}
226	
227	func TestGCCollectsEmptyObjectAsZeroBytes(t *testing.T) {
228		root := filepath.Join(t.TempDir(), "vault")
229		store := New(root)
230		if _, err := store.Put("empty.txt", writeFile(t, "")); err != nil {
231			t.Fatal(err)
232		}
233		if _, err := store.Put("empty.txt", writeFile(t, "nonempty")); err != nil {
234			t.Fatal(err)
235		}
236		report, err := store.GC(false)
237		if err != nil {
238			t.Fatal(err)
239		}
240		if report.Deleted != 1 || report.Bytes != 0 {
241			t.Fatalf("deleted=%d bytes=%d", report.Deleted, report.Bytes)
242		}
243	}
244	
245	func TestGCRequiresExistingInitializedRepository(t *testing.T) {
246		missing := filepath.Join(t.TempDir(), "vault")
247		if _, err := New(missing).GC(false); err == nil {
248			t.Fatal("expected error for missing root")
249		}
250		if _, err := os.Stat(missing); !os.IsNotExist(err) {
251			t.Fatal("GC created the missing root")
252		}
253		// Root exists but was never initialized.
254		empty := filepath.Join(t.TempDir(), "vault")
255		if err := os.MkdirAll(empty, 0o755); err != nil {
256			t.Fatal(err)
257		}
258		if _, err := New(empty).GC(false); err == nil {
